"""
gen_manifest.py -- regenerate roblox/src/Manifest_*.lua from the Blender exports.

    python3 roblox/tools/gen_manifest.py     (run from the repo root)
"""
import json
import os

STUD = 1 / 0.28
ROOT = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
PILLARS = {"steam": "steam_cutter_1888", "rowing": "rowing_cutter_25ft"}

HEADER = """--!nonstrict
-- AUTO-GENERATED by roblox/tools/gen_manifest.py from
-- boats/exports/{key}/manifest.json -- do not edit by hand.
-- Positions are in studs, in the Blender frame: +X forward, +Y port, +Z up.
-- BuildBoat applies the -Z (Roblox forward) rotation on assembly.
"""


def main():
    for key, lid in PILLARS.items():
        m = json.load(open(os.path.join(ROOT, "boats", "exports", key, "manifest.json")))
        parts = [p for p in m["parts"] if p["role"] != "other"]
        out = [HEADER.format(key=key), "return {", f'\tboat_id = "{lid}",',
               f"\tstud_per_m = {STUD:.6f},", "\tparts = {{"]
        for p in parts:
            o = [round(v * STUD, 4) for v in p["origin_m"]]
            s = [round(v * STUD, 4) for v in p["size_m"]]
            out.append(f'\t\t{{ name = "{p["name"]}", role = "{p["role"]}",'
                       f' origin = Vector3.new({o[0]}, {o[1]}, {o[2]}),'
                       f' size = Vector3.new({s[0]}, {s[1]}, {s[2]}),'
                       f' verts = {p["vertices"]} }},')
        out += ["\t},", "}", ""]
        path = os.path.join(ROOT, "roblox", "src", f"Manifest_{lid}.lua")
        open(path, "w").write("\n".join(out))
        print("wrote", path, len(parts), "parts")


if __name__ == "__main__":
    main()
